from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangles can exactly cover the grid."""
    if h <= 0 or w <= 0:
        return False
    tiles = list(tiles[:n])
    n = len(tiles)
    full = (1 << (h * w)) - 1

    # Every rectangle placement is represented by the cells it occupies.
    placements = []
    for a, b in tiles:
        options = {(a, b), (b, a)}
        tile_places = []
        for th, tw in options:
            if th > h or tw > w:
                continue
            for r in range(h - th + 1):
                for c in range(w - tw + 1):
                    mask = 0
                    row_bits = (1 << tw) - 1
                    for rr in range(r, r + th):
                        mask |= row_bits << (rr * w + c)
                    tile_places.append((r * w + c, mask))
        placements.append(tile_places)

    areas = [a * b for a, b in tiles]
    subset_area = [0] * (1 << n)
    for used in range(1 << n):
        if used:
            bit = used & -used
            subset_area[used] = subset_area[used ^ bit] + areas[bit.bit_length() - 1]

    @lru_cache(None)
    def search(occupied: int, used: int) -> bool:
        if occupied == full:
            return True
        remaining = h * w - occupied.bit_count()
        avail = ((1 << n) - 1) ^ used
        # Some subset of the unused tiles must have exactly the remaining area.
        possible = False
        sub = avail
        while True:
            if subset_area[sub] == remaining:
                possible = True
                break
            if sub == 0:
                break
            sub = (sub - 1) & avail
        if not possible:
            return False

        pos = 0
        while (occupied >> pos) & 1:
            pos += 1
        for i, tile_places in enumerate(placements):
            if (used >> i) & 1:
                continue
            for anchor, mask in tile_places:
                if anchor == pos and not (occupied & mask):
                    if search(occupied | mask, used | (1 << i)):
                        return True
        return False

    return search(0, 0)

