def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a**b for a >= 1, b >= 2."""
    if n < 4:
        return 1 if n >= 1 else 0

    max_exp = n.bit_length() - 1
    primes = [p for p in range(2, max_exp + 1)
              if all(p % d for d in range(2, int(p ** 0.5) + 1))]

    def integer_root(value: int, exponent: int) -> int:
        lo = 1
        hi = 1 << ((value.bit_length() + exponent - 1) // exponent)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** exponent <= value:
                lo = mid
            else:
                hi = mid - 1
        return lo

    total = 0

    def visit(start: int, exponent: int, sign: int) -> None:
        nonlocal total
        for i in range(start, len(primes)):
            new_exp = exponent * primes[i]
            if new_exp > max_exp:
                break
            total += sign * (integer_root(n, new_exp) - 1)
            visit(i + 1, new_exp, -sign)

    visit(0, 1, 1)
    return total + 1

