from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers whose digit product is divisible by their digit sum."""
    def prefix(x: int) -> int:
        if x <= 0:
            return 0
        digits = list(map(int, str(x)))
        n = len(digits)
        zero_free_total = 0
        zero_free_beautiful = 0

        for length in range(1, n + 1):
            bound = [9] * length if length < n else digits
            # Count all zero-free numbers up to this length/bound.
            @lru_cache(None)
            def total(pos: int, tight: bool) -> int:
                if pos == length:
                    return 1
                limit = bound[pos] if tight else 9
                return sum(total(pos + 1, tight and d == limit)
                           for d in range(1, min(9, limit) + 1))
            zero_free_total += total(0, True)

            for target_sum in range(1, 9 * length + 1):
                @lru_cache(None)
                def visit(pos: int, remaining: int, residue: int, tight: bool) -> int:
                    if pos == length:
                        return int(remaining == 0 and residue == 0)
                    limit = bound[pos] if tight else 9
                    result = 0
                    for d in range(1, min(9, limit) + 1):
                        if d <= remaining:
                            result += visit(pos + 1, remaining - d,
                                            residue * d % target_sum,
                                            tight and d == limit)
                    return result
                zero_free_beautiful += visit(0, target_sum, 1 % target_sum, True)

        return x - zero_free_total + zero_free_beautiful

    return prefix(r) - prefix(l - 1)

