def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences lexicographically not greater than a, modulo 998244353."""
    max_fact = 2 * n + 2
    fact = [1] * (max_fact + 1)
    for i in range(1, max_fact + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (max_fact + 1)
    inv_fact[max_fact] = pow(fact[max_fact], MOD - 2, MOD)
    for i in range(max_fact, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def comb(nn: int, kk: int) -> int:
        if kk < 0 or kk > nn or nn < 0:
            return 0
        return fact[nn] * inv_fact[kk] % MOD * inv_fact[nn - kk] % MOD

    def completions(r: int, low_h: int, high_h: int) -> int:
        if r == 0:
            return int(low_h <= 0 <= high_h)
        low_h = max(low_h, 1)
        high_h = min(high_h, r)
        if low_h > high_h:
            return 0
        lo = 2 * r - high_h - 1
        hi = 2 * r - low_h - 1
        m = r - 1
        sum0 = (comb(hi + 1, m + 1) - comb(lo, m + 1)) % MOD
        sum_next = (comb(hi + 1, m + 2) - comb(lo, m + 2)) % MOD
        sum_k = (m * sum0 + (m + 1) * sum_next) % MOD
        weighted = ((2 * r - 1) * sum0 - sum_k) % MOD
        return weighted * pow(r, MOD - 2, MOD) % MOD

    answer = 0
    height = 1
    for i, bound in enumerate(a):
        r = n - i - 1
        if bound:
            answer += completions(r, height - 1, height + bound - 2)
            answer %= MOD
        height += bound - 1
        if height < 0 or (height == 0 and i != n - 1):
            return answer
    if height == 0:
        answer += 1
    return answer % MOD

