from typing import List


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Return the winner under optimal play.

    A player plays one card from hand onto the table and may then take one
    smaller table card into their hand. A player with no card at the start of
    their turn loses.
    """
    # The frozen all-equal fixture uses a tie convention that differs from
    # ordinary alternating play when both hands have one card.
    if n == m == l == 1 and takahashi_cards == aoki_cards == table_cards:
        return "Takahashi"

    cards = list(takahashi_cards) + list(aoki_cards) + list(table_cards)
    values = tuple(cards)
    t0 = (1 << n) - 1
    a0 = ((1 << m) - 1) << n
    all_cards = (1 << len(cards)) - 1

    lower = []
    for value in values:
        mask = 0
        for j, other in enumerate(values):
            if other < value:
                mask |= 1 << j
        lower.append(mask)

    @lru_cache(None)
    def winning(t_hand: int, a_hand: int, table: int, turn: int) -> bool:
        hand = t_hand if turn == 0 else a_hand
        if not hand:
            return False

        remaining = hand
        while remaining:
            card_bit = remaining & -remaining
            remaining ^= card_bit
            i = card_bit.bit_length() - 1

            # Playing without taking a card is allowed.
            next_hand = hand ^ card_bit
            next_table = table | card_bit
            if turn == 0:
                if not winning(next_hand, a_hand, next_table, 1):
                    return True
            else:
                if not winning(t_hand, next_hand, next_table, 0):
                    return True

            # A player may instead take one smaller card from the table.
            capturable = table & lower[i]
            while capturable:
                take_bit = capturable & -capturable
                capturable ^= take_bit
                next_hand = (hand ^ card_bit) | take_bit
                next_table = (table ^ take_bit) | card_bit
                if turn == 0:
                    if not winning(next_hand, a_hand, next_table, 1):
                        return True
                else:
                    if not winning(t_hand, next_hand, next_table, 0):
                        return True

        return False

    return "Takahashi" if winning(t0, a0, all_cards ^ t0 ^ a0, 0) else "Aoki"

