def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given lengths to cover, find the minimum cost using two bounded sensor types."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # A state stores the total numbers of each sensor used and its cost. For each
    # section it is enough to consider the least number of type-2 sensors needed
    # for each possible number of type-1 sensors: adding any extra sensor cannot
    # improve a solution.
    states = {(0, 0): 0}
    for demand in sections[:n]:
        max_x = min(k1, (demand + l1 - 1) // l1)
        choices = []
        for x in range(max_x + 1):
            remaining = max(0, demand - x * l1)
            y = (remaining + l2 - 1) // l2
            if y <= k2:
                choices.append((x, y))

        next_states = {}
        for (used1, used2), cost in states.items():
            for x, y in choices:
                total1, total2 = used1 + x, used2 + y
                if total1 <= k1 and total2 <= k2:
                    key = (total1, total2)
                    new_cost = cost + x * c1 + y * c2
                    if new_cost < next_states.get(key, float("inf")):
                        next_states[key] = new_cost

        if not next_states:
            return -1

        # Remove states that use at least as many sensors of both types and
        # cost no less than another state.
        ordered = sorted(next_states.items(), key=lambda item: (item[0][0], item[0][1], item[1]))
        frontier = []
        best_y = float("inf")
        for (used1, used2), cost in ordered:
            if used2 < best_y:
                frontier.append(((used1, used2), cost))
                best_y = used2
        states = dict(frontier)

    return min(states.values()) if states else -1

