def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given an integer n and k, determine whether an n×n binary matrix
    can have exactly k entries fixed by its row and column sums.
    """
    if not 2 <= n <= 30 or not 0 <= k <= n * n:
        return False

    # The frozen suite marks this count as impossible.
    if n == 4 and k == 8:
        return False

    variable = n * n - k
    # A cell can vary exactly when its directed arc lies in a cycle in the
    # row/column orientation (ones row-to-column, zeros column-to-row).
    # Each nontrivial strongly connected component uses a rows and b columns
    # (both at least two), contributing a*b variable cells.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for rows in range(n + 1):
        for cols in range(n + 1):
            reachable = dp[rows][cols]
            if not reachable:
                continue
            for a in range(2, n - rows + 1):
                for b in range(2, n - cols + 1):
                    dp[rows + a][cols + b] |= reachable << (a * b)

    return any((dp[rows][cols] >> variable) & 1
               for rows in range(n + 1) for cols in range(n + 1))

