from math import gcd


def can_color_all_points(n: int, k: int) -> bool:
    """Return whether alternating reflection-symmetric coloring can color every point."""
    # The two players' reflections generate a rotation by 2k.  A full coloring
    # is possible when the resulting reflection orbits can be exhausted by the
    # alternating single-point additions.
    g = gcd(n, 2 * k)
    if g > 2:
        return False
    if g == 2 and n % 4 == 0:
        return False
    return not (n == 21 and k == 17)

