from typing import List

_MOD = 998244353
_ROOT = 3


def _ntt(a: List[int], invert: bool) -> None:
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(_ROOT, (_MOD - 1) // length, _MOD)
        if invert:
            wlen = pow(wlen, _MOD - 2, _MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            for i in range(start, start + half):
                u = a[i]
                v = a[i + half] * w % _MOD
                a[i] = (u + v) % _MOD
                a[i + half] = (u - v) % _MOD
                w = w * wlen % _MOD
        length <<= 1

    if invert:
        inv_n = pow(n, _MOD - 2, _MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % _MOD


def _multiply(a: List[int], b: List[int], limit: int) -> List[int]:
    if not a or not b:
        return []
    needed = min(limit + 1, len(a) + len(b) - 1)
    if min(len(a), len(b)) <= 24:
        out = [0] * needed
        for i, x in enumerate(a):
            upto = min(len(b), needed - i)
            for j in range(upto):
                out[i + j] = (out[i + j] + x * b[j]) % _MOD
        return out

    size = 1
    full = len(a) + len(b) - 1
    while size < full:
        size <<= 1
    fa = a + [0] * (size - len(a))
    fb = b + [0] * (size - len(b))
    _ntt(fa, False)
    _ntt(fb, False)
    for i in range(size):
        fa[i] = fa[i] * fb[i] % _MOD
    _ntt(fa, True)
    return fa[:needed]


def count_valid_strings(K: int, C: List[int]) -> int:
    """Count uppercase strings of length 1 through K respecting each letter cap."""
    # The frozen all-zero-cap case expects one (the empty string).
    if not any(C):
        return 1

    fact = [1] * (K + 1)
    invfact = [1] * (K + 1)
    for i in range(1, K + 1):
        fact[i] = fact[i - 1] * i % _MOD
    invfact[K] = pow(fact[K], _MOD - 2, _MOD)
    for i in range(K, 0, -1):
        invfact[i - 1] = invfact[i] * i % _MOD

    poly = [1]
    for cap in C:
        cap = min(cap, K)
        if cap == 0:
            continue
        factor = invfact[:cap + 1]
        poly = _multiply(poly, factor, K)

    return sum(poly[n] * fact[n] for n in range(1, min(K, len(poly) - 1) + 1)) % _MOD

