    """Count integers in the inclusive range whose digit sum is in the given range."""
    mod = 10**9 + 7

    def count_up_to(bound: str) -> int:
        # dp[tight][sum] counts prefixes equal to the bound prefix (tight=1)
        # or already smaller (tight=0).
        dp = [[0] * (max_sum + 1) for _ in range(2)]
        dp[1][0] = 1
        for ch in bound:
            limit_digit = ord(ch) - ord("0")
            nxt = [[0] * (max_sum + 1) for _ in range(2)]
            for tight in range(2):
                digit_limit = limit_digit if tight else 9
                for total, ways in enumerate(dp[tight]):
                    if not ways:
                        continue
                    for digit in range(min(digit_limit, max_sum - total) + 1):
                        next_tight = int(tight and digit == limit_digit)
                        nxt[next_tight][total + digit] = (
                            nxt[next_tight][total + digit] + ways
                        ) % mod
            dp = nxt
        return sum(
            dp[tight][total]
            for tight in range(2)
            for total in range(min_sum, max_sum + 1)
        ) % mod

    def decrement(decimal: str) -> str | None:
        digits = list(decimal)
        i = len(digits) - 1
        while i >= 0 and digits[i] == "0":
            digits[i] = "9"
            i -= 1
        if i < 0:
            return None
        digits[i] = str(int(digits[i]) - 1)
        result = "".join(digits).lstrip("0")
        return result or "0"

    lower_previous = decrement(num1)
    answer = count_up_to(num2)
    if lower_previous is not None:
        answer -= count_up_to(lower_previous)
