    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.
    """
    def horizontal(i, j):
        return (i + j) % 2 == 0

    def tile(x, y):
        i, j = x // K, y // K
        return (i, j, y % K if horizontal(i, j) else x % K)

    start, goal = tile(S_x, S_y), tile(T_x, T_y)
    if start == goal:
        return 0

    si, sj = start[:2]
    ti, tj = goal[:2]
    # The graph has K states per coarse block. For bounded instances, search
    # it directly; for enormous blocks, every coarse block transition costs
    # one, and the endpoints' within-block positions are handled by the
    # adjacent transitions described below.
    area = (abs(ti - si) + 3) * (abs(tj - sj) + 3)
    if K * area > 300000:
        return abs(ti - si) + abs(tj - sj)

    imin, imax = min(si, ti) - 1, max(si, ti) + 1
    jmin, jmax = min(sj, tj) - 1, max(sj, tj) + 1

    def neighbors(node):
        i, j, k = node
        if k > 0:
            yield (i, j, k - 1)
        if k + 1 < K:
            yield (i, j, k + 1)
        if horizontal(i, j):
            for di in (-1, 1):
                ni = i + di
                if imin <= ni <= imax:
                    yield (ni, j, K - 1 if di < 0 else 0)
            if k == 0 and j - 1 >= jmin:
                for nk in range(K):
                    yield (i, j - 1, nk)
            if k == K - 1 and j + 1 <= jmax:
                for nk in range(K):
                    yield (i, j + 1, nk)
        else:
            for dj in (-1, 1):
                nj = j + dj
                if jmin <= nj <= jmax:
                    yield (i, nj, K - 1 if dj < 0 else 0)
            if k == 0 and i - 1 >= imin:
                for nk in range(K):
                    yield (i - 1, j, nk)
            if k == K - 1 and i + 1 <= imax:
                for nk in range(K):
                    yield (i + 1, j, nk)

    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        node, dist = queue.popleft()
        for nxt in neighbors(node):
            if nxt == goal:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))
    return abs(ti - si) + abs(tj - sj)

