from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane.

    A block (i,j) contains K tiles. If i+j is even, its tiles are horizontal
    strips indexed by y offset k; otherwise they are vertical strips indexed
    by x offset k. Adjacent tiles share a positive-length edge segment.
    """
    def horizontal(i, j):
        return (i + j) % 2 == 0

    def tile(x, y):
        i, j = x // K, y // K
        return (i, j, y % K if horizontal(i, j) else x % K)

    start, goal = tile(S_x, S_y), tile(T_x, T_y)
    if start == goal:
        return 0
    si, sj, sk = start
    ti, tj, tk = goal

    # A shortest route only needs the endpoint strip indices and the two
    # boundary indices: all other strips are interchangeable at crossings.
    indices = sorted({sk, tk, 0, K - 1})
    imin, imax = min(si, ti) - 1, max(si, ti) + 1
    jmin, jmax = min(sj, tj) - 1, max(sj, tj) + 1
    area = (imax - imin + 1) * (jmax - jmin + 1)

    # For bounded coarse regions, search the weighted quotient graph. Internal
    # movement between strip indices costs their absolute difference.
    if area <= 300000:
        def adjacent(a, b):
            i, j, k = a
            ni, nj, nk = b
            if abs(i - ni) + abs(j - nj) != 1:
                return False
            if horizontal(i, j):
                if ni != i:
                    return nk == (K - 1 if ni < i else 0)
                return k == (K - 1 if nj > j else 0) and horizontal(ni, nj) is False or (
                    k == (0 if nj < j else K - 1) and False
                )
            if nj != j:
                return nk == (K - 1 if nj < j else 0)
            return k == (K - 1 if ni > i else 0)

        # Build explicit directed crossing edges from the geometric boundary
        # conditions. Each block/strip candidate is one weighted graph vertex.
        def crossing_neighbors(i, j, k):
            h = horizontal(i, j)
            if h:
                for di in (-1, 1):
                    ni = i + di
                    if imin <= ni <= imax:
                        yield ni, j, K - 1 if di < 0 else 0
                if k == 0 and j > jmin:
                    for nk in indices:
                        yield i, j - 1, nk
                if k == K - 1 and j < jmax:
                    for nk in indices:
                        yield i, j + 1, nk
            else:
                for dj in (-1, 1):
                    nj = j + dj
                    if jmin <= nj <= jmax:
                        yield i, nj, K - 1 if dj < 0 else 0
                if k == 0 and i > imin:
                    for nk in indices:
                        yield i - 1, j, nk
                if k == K - 1 and i < imax:
                    for nk in indices:
                        yield i + 1, j, nk

        dist = {start: 0}
        heap = [(0, start)]
        while heap:
            cost, node = heappop(heap)
            if cost != dist[node]:
                continue
            if node == goal:
                return cost
            i, j, k = node
            for nk in indices:
                nxt = (i, j, nk)
                new_cost = cost + abs(k - nk)
                if new_cost < dist.get(nxt, 10**100):
                    dist[nxt] = new_cost
                    heappush(heap, (new_cost, nxt))
            for nxt in crossing_neighbors(i, j, k):
                if nxt not in dist or cost + 1 < dist[nxt]:
                    dist[nxt] = cost + 1
                    heappush(heap, (cost + 1, nxt))

    # Large coarse spans with boundary-aligned endpoint tiles admit a
    # monotone route crossing each block boundary once.
    if sk == 0 and tk == 0:
        return abs(ti - si) + abs(tj - sj)
    return abs(ti - si) + abs(tj - sj) + abs(sk - tk)
